<span class="line"><span style="color:#61AFEF;">-rw-r--r--.</span><span style="color:#D19A66;"> 1</span><span style="color:#98C379;"> root</span><span style="color:#98C379;"> root</span><span style="color:#D19A66;"> 11357</span><span style="color:#98C379;"> Jan</span><span style="color:#D19A66;">  10</span><span style="color:#98C379;"> 01:36</span><span style="color:#98C379;"> LICENSE</span></span>
